/**
 * The project's shared framework FeatureSelector. One instance holds the whole
 * flag registry, so every caller sees the same registered features.
 *
 * @return \rtCamp\WPFramework\Utils\FeatureSelector Shared feature selector.
 */
public static function feature_selector(): \rtCamp\WPFramework\Utils\FeatureSelector {
	static $instance = null;

	if ( null === $instance ) {
		$instance = new \rtCamp\WPFramework\Utils\FeatureSelector( '{{context_slug}}' );
	}

	return $instance;
}
